import { describe, expect, it } from "vitest";
import { parseSkillState, SkillCatalogSchema } from "./skill";

const validSkillState = {
  active_skill: {
    skill_id: "card_replace",
    ordered_block_id: "card_replace__main",
    step_id: "start",
  },
  blocks: { card_replace__main: { status: "active" } },
  evaluated_conditions: { "session.card_replace.ready": true },
  memory: {
    "card_replace.reason": {
      value: "lost",
      source: "llm",
      scope: "skill",
      description: null,
    },
  },
};

describe("parseSkillState", () => {
  it("parses a valid skill_state payload", () => {
    const parsed = parseSkillState(validSkillState);
    expect(parsed?.active_skill?.skill_id).toBe("card_replace");
    expect(parsed?.blocks["card_replace__main"]?.status).toBe("active");
  });

  it("parses skill_state from an older backend that omits tools and llm_calls", () => {
    // validSkillState carries neither key; the schema defaults must fill them.
    const parsed = parseSkillState(validSkillState);
    expect(parsed?.tools).toEqual({});
    expect(parsed?.llm_calls).toEqual([]);
  });

  it("returns undefined for an absent payload", () => {
    expect(parseSkillState(undefined)).toBeUndefined();
  });

  it("returns undefined for a malformed payload instead of throwing", () => {
    expect(parseSkillState({ blocks: "not-a-record" })).toBeUndefined();
    expect(parseSkillState("nonsense")).toBeUndefined();
  });
});

describe("SkillCatalogSchema", () => {
  it("parses a catalog entry and tolerates unknown step kinds", () => {
    const catalog = SkillCatalogSchema.parse({
      card_replace: {
        id: "card_replace",
        name: "Card Replace",
        description: null,
        is_default: false,
        engine_managed: false,
        disabled: false,
        sections: [
          {
            type: "prose",
            segments: [{ text: "if-scoped", condition: "session.card_replace.ready" }],
          },
          { type: "ordered_block", block_id: "main" },
        ],
        blocks: {
          main: {
            ordered_block_id: "card_replace__main",
            complete_when: null,
            // A step kind this frontend version doesn't know yet must not fail parsing.
            steps: [{ id: "s1", kind: "brand_new_kind", extra_field: 42 }],
          },
        },
        referenced_skills: [],
        tool_names: [],
      },
    });
    expect(catalog["card_replace"]?.sections).toHaveLength(2);
    expect(catalog["card_replace"]?.blocks["main"]?.steps[0]?.kind).toBe("brand_new_kind");
    expect(catalog["card_replace"]?.hidden).toBe(false);
  });

  it("keeps hidden catalog metadata and defaults it when the backend omits it", () => {
    const withHidden = SkillCatalogSchema.parse({
      authenticate: {
        id: "authenticate",
        name: "Authenticate",
        description: null,
        is_default: false,
        engine_managed: false,
        disabled: false,
        hidden: true,
        sections: [],
        blocks: {},
        referenced_skills: [],
        tool_names: [],
      },
    });
    expect(withHidden["authenticate"]?.hidden).toBe(true);

    const withoutHidden = SkillCatalogSchema.parse({
      card_replace: {
        id: "card_replace",
        name: "Card Replace",
        description: null,
        is_default: false,
        engine_managed: false,
        disabled: false,
        sections: [],
        blocks: {},
        referenced_skills: [],
        tool_names: [],
      },
    });
    expect(withoutHidden["card_replace"]?.hidden).toBe(false);
  });
});
